<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\ThemeVersion\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Document\ThemeVersion\Domain\ValueObject\ThemeVersionThemeVO;
use Civi\Lughauth\Features\Document\Theme\Domain\ThemeRef;

trait ThemeVersionThemeAccessor
{
    private ThemeVersionThemeVO $_theme;
    public function getTheme(): ThemeRef
    {
        return $this->_theme->value();
    }
    public function theme(): ThemeVersionThemeVO
    {
        return $this->_theme;
    }
    public function isThemeChanged(?self $original = null): bool
    {
        return !$this->_theme->equals($original?->_theme);
    }
    public function withTheme(ThemeVersionThemeVO|ThemeRef $theme): self
    {
        $copy = clone $this;
        $copy->_theme = ThemeVersionThemeVO::from($theme);
        return $copy;
    }
}
